{"command":"python3 - <<'PY'
# token seq hypothesized
# map types to ints/names
seq=[]
pos=[] # (file,line, name)
def add(f,line,name): seq.append(name); pos.append((f,line))
for f, fn in [('a','foo'),('b','bar')]:
    add(f,1,'File')
    add(f,3,'FuncDecl'); add(f,3,'Ident') # fn
    add(f,3,'FuncType'); add(f,3,'FieldList'); add(f,3,'Block')
    stmts=[('Assign','Ident','Lit'),('Assign','Ident','Lit'),('Assign','Ident','Bin','Ident','Ident'),('Expr','Call','Ident','Ident'),('Assign','Ident','Lit'),('Assign','Ident','Lit'),('Assign','Ident','Bin','Ident','Ident'),('Expr','Call','Ident','Ident')]
    lines=[4,5,6,7,8,9,10,11]
    if f=='b': stmts=stmts[:4]; lines=lines[:4]
    for st,ln in zip(stmts,lines):
        for tok in st: add(f,ln,tok)
print(len(seq), seq)
# Build suffix trie nodes: each node children dict, leaves list
import sys
sys.setrecursionlimit(10000)
class N:
    __slots__=('children','occ','term')
    def __init__(self): self.children={}; self.occ=[]
root=N()
for i in range(len(seq)):
    node=root
    node.occ.append(i)
    for j in range(i,len(seq)):
        t=seq[j]
        if t not in node.children: node.children[t]=N()
        node=node.children[t]; node.occ.append(i)
    # termination

def walk(node, path, edgedepth):
    # edgedepth = number trie nodes? compressed edgedepth later
    if len(node.occ)>=2 and path:
        # check if branching or terminal: node has !=1 child or some suffix ends here
        ends = any(i+len(path)>=len(seq) or False for i in node.occ) # not
        # number of distinct next tokens
        nexts=set()
        for i in node.occ:
            if i+len(path)<len(seq): nexts.add(seq[i+len(path)])
            else: nexts.add(None)
        if len(nexts)>=2 or len(node.children)!=1:
            # interval lines from first occ
            print(f"len={len(path)} branching_next={len(nexts)} occ={node.occ} path={path} lines={[ (pos[i][0],pos[i][1], pos[i+len(path)-1][1] if len(path) else None) for i in node.occ]}")
    for t,ch in node.children.items():
        walk(ch, path+[t], edgedepth+1)
walk(root, [],0)
PY"}

