package main

import (
	"bufio"
	"flag"
	"fmt"
	"html"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var usageText = "Usage: dupl [flags] [paths]\n" +
	"\n" +
	"Paths:\n" +
	"  If the given path is a file, dupl will use it regardless of\n" +
	"  the file extension. If it is a directory, it will recursively\n" +
	"  search for *.go files in that directory.\n" +
	"\n" +
	"  If no path is given, dupl will recursively search for *.go\n" +
	"  files in the current directory.\n" +
	"\n" +
	"Flags:\n" +
	"  -files\n" +
	"    \tread file names from stdin one at each line\n" +
	"  -html\n" +
	"    \toutput the results as HTML, including duplicate code fragments\n" +
	"  -plumbing\n" +
	"    \tplumbing (easy-to-parse) output for consumption by scripts or tools\n" +
	"  -t, -threshold size\n" +
	"    \tminimum token sequence size as a clone (default 15)\n" +
	"  -vendor\n" +
	"    \tcheck files in vendor directory\n" +
	"  -v, -verbose\n" +
	"    \texplain what is being done\n" +
	"\n" +
	"Examples:\n" +
	"  dupl -t 100\n" +
	"    \tSearch clones in the current directory of size at least\n" +
	"    \t100 tokens.\n" +
	"  dupl $(find app/ -name '*_test.go')\n" +
	"    \tSearch for clones in tests in the app directory.\n" +
	"  find app/ -name '*_test.go' |dupl -files\n" +
	"    \tThe same as above.\n"

func main() {
	var (
		filesFlag    bool
		htmlFlag     bool
		plumbingFlag bool
		threshold    int
		vendorFlag   bool
		verboseFlag  bool
	)
	flag.Usage = func() {
		fmt.Fprint(flag.CommandLine.Output(), usageText)
	}
	flag.BoolVar(&filesFlag, "files", false, "")
	flag.BoolVar(&htmlFlag, "html", false, "")
	flag.BoolVar(&plumbingFlag, "plumbing", false, "")
	flag.IntVar(&threshold, "t", 15, "")
	flag.IntVar(&threshold, "threshold", 15, "")
	flag.BoolVar(&vendorFlag, "vendor", false, "")
	flag.BoolVar(&verboseFlag, "v", false, "")
	flag.BoolVar(&verboseFlag, "verbose", false, "")
	flag.Parse()

	if htmlFlag && plumbingFlag {
		log.Fatal("you can have either plumbing or HTML output")
	}

	if verboseFlag {
		log.Println("Building suffix tree")
	}

	filenames := collectFilenames(filesFlag, vendorFlag)

	files := make([]*SourceFile, 0, len(filenames))
	for _, filename := range filenames {
		sf, err := parseFile(filename)
		if err != nil {
			log.Println(err)
			continue
		}
		files = append(files, sf)
	}

	if verboseFlag {
		log.Println("Searching for clones")
	}

	groups := FindClones(files, threshold)

	switch {
	case htmlFlag:
		printHTML(os.Stdout, groups)
	case plumbingFlag:
		printPlumbing(os.Stdout, groups)
	default:
		printText(os.Stdout, groups)
	}
}

func collectFilenames(readFromStdin bool, vendorFlag bool) []string {
	if readFromStdin {
		var filenames []string
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			filenames = append(filenames, scanner.Text())
		}
		return filenames
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	var filenames []string
	for _, path := range paths {
		info, err := os.Lstat(path)
		if err != nil {
			log.Fatal(err)
		}
		if !info.IsDir() {
			filenames = append(filenames, path)
			continue
		}
		_ = filepath.Walk(path, func(walked string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			if info == nil {
				return nil
			}
			if !vendorFlag && hasVendorComponent(walked) {
				if info.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
			if info.IsDir() {
				return nil
			}
			if filepath.Ext(walked) == ".go" {
				filenames = append(filenames, walked)
			}
			return nil
		})
	}
	return filenames
}

func hasVendorComponent(path string) bool {
	// Clean leading ./ etc. is irrelevant: looking for a component that is
	// exactly "vendor".
	parts := strings.Split(filepath.ToSlash(path), "/")
	for _, part := range parts {
		if part == "vendor" {
			return true
		}
	}
	return false
}

func sortedClones(clones []*Clone) []*Clone {
	out := make([]*Clone, len(clones))
	copy(out, clones)
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Filename != out[j].Filename {
			return out[i].Filename < out[j].Filename
		}
		if out[i].Start != out[j].Start {
			return out[i].Start < out[j].Start
		}
		return out[i].End < out[j].End
	})
	return out
}

func printText(out *os.File, groups []*Group) {
	w := bufio.NewWriter(out)
	defer w.Flush()
	for _, group := range groups {
		clones := sortedClones(group.Clones)
		fmt.Fprintf(w, "found %d clones:\n", len(clones))
		for _, clone := range clones {
			fmt.Fprintf(w, "  %s:%d,%d\n", clone.Filename, clone.Start, clone.End)
		}
	}
	fmt.Fprintf(w, "\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(out *os.File, groups []*Group) {
	w := bufio.NewWriter(out)
	defer w.Flush()
	for _, group := range groups {
		clones := sortedClones(group.Clones)
		for i, clone := range clones {
			other := clones[(i+1)%len(clones)]
			fmt.Fprintf(w, "%s:%d-%d: duplicate of %s:%d-%d\n",
				clone.Filename, clone.Start, clone.End,
				other.Filename, other.Start, other.End)
		}
	}
}

const htmlHeader = "<!DOCTYPE html>\n" +
	"<meta charset=\"utf-8\"/>\n" +
	"<title>Duplicates</title>\n" +
	"<style>\n" +
	"\tpre {\n" +
	"\t\tbackground-color: #FFD;\n" +
	"\t\tborder: 1px solid #E2E2E2;\n" +
	"\t\tpadding: 1ex;\n" +
	"\t}\n" +
	"</style>\n"

func printHTML(out *os.File, groups []*Group) {
	w := bufio.NewWriter(out)
	defer w.Flush()
	fmt.Fprint(w, htmlHeader)
	for i, group := range groups {
		clones := sortedClones(group.Clones)
		fmt.Fprintf(w, "<h1>#%d found %d clones</h1>\n", i+1, len(clones))
		for _, clone := range clones {
			fmt.Fprintf(w, "<h2>%s:%d</h2>\n", clone.Filename, clone.Start)
			fmt.Fprintf(w, "<pre>%s</pre>\n", html.EscapeString(cloneFragment(clone)))
		}
	}
}

func cloneFragment(clone *Clone) string {
	if clone.file == nil {
		return ""
	}
	data := clone.file.Content
	start := clone.startOffset
	end := clone.endOffset
	if start < 0 {
		start = 0
	}
	if end < start {
		end = start
	}
	if start > len(data) {
		start = len(data)
	}
	if end > len(data) {
		end = len(data)
	}
	// Start of the line containing the clone.
	lineStart := start
	for lineStart > 0 && data[lineStart-1] != '\n' {
		lineStart--
	}
	if end < lineStart {
		end = lineStart
	}
	raw := make([]byte, 0, end-lineStart)
	raw = append(raw, data[lineStart:end]...)
	// Blank out the part of the first line that precedes the clone while
	// retaining whitespace, so that indented fragments stay aligned.
	prefixLen := start - lineStart
	if prefixLen > len(raw) {
		prefixLen = len(raw)
	}
	for i := 0; i < prefixLen; i++ {
		if raw[i] != ' ' && raw[i] != '\t' && raw[i] != '\r' {
			raw[i] = ' '
		}
	}
	return dedent(string(raw))
}

func dedent(s string) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	lines := strings.Split(s, "\n")
	// Determine the indentation shared by all lines following the first.
	common := ""
	first := true
	for _, line := range lines[1:] {
		if strings.Trim(line, " \t\r") == "" {
			continue
		}
		indent := line[:len(line)-len(strings.TrimLeft(line, " \t"))]
		if first {
			common = indent
			first = false
			continue
		}
		common = commonPrefix(common, indent)
		if common == "" {
			break
		}
	}
	if common == "" {
		return s
	}
	for i, line := range lines {
		if strings.HasPrefix(line, common) {
			lines[i] = line[len(common):]
		}
	}
	return strings.Join(lines, "\n")
}

func commonPrefix(a, b string) string {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	i := 0
	for i < n && a[i] == b[i] {
		i++
	}
	return a[:i]
}
