var tokenIDs = map[string]int{}
var nextTokenID = 1

func tokenIDFor(node ast.Node) int {
	name := fmt.Sprintf("%T", node)
	if id, ok := tokenIDs[name]; ok {
		return id
	}
	id := nextTokenID
	nextTokenID++
	tokenIDs[name] = id
	return id
}

type Token struct {
	ID          int
	TypeName    string
	FileIndex   int // index into the parsed-files slice used for one run
	IndexInFile int
	Line        int
	EndLine     int
	Offset      int // byte offset of node start within the file
	EndOffset   int // byte offset of node end within the file
	SubtreeSize int
}

type SourceFile struct {
	Name    string
	Content []byte
	Tokens  []Token
}

func parseFile(filename string) (*SourceFile, error) {
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, filename, content, 0)
	if err != nil {
		return nil, err
	}
	sf := &SourceFile{Name: filename, Content: content}
	tk := &tokenizer{fset: fset, file: sf}
	tk.walk(node)
	for i := range sf.Tokens {
		sf.Tokens[i].IndexInFile = i
	}
	return sf, nil
}

type tokenizer struct {
	fset *token.FileSet
	file *SourceFile
}

func (t *tokenizer) walk(node ast.Node) int {
	if node == nil {
		return 0
	}
	switch node.(type) {
	case *ast.Comment, *ast.CommentGroup:
		return 0
	}
	if decl, ok := node.(*ast.GenDecl); ok && decl.Tok == token.IMPORT {
		return 0
	}

	pos := t.fset.Position(node.Pos())
	end := t.fset.Position(node.End())
	index := len(t.file.Tokens)
	t.file.Tokens = append(t.file.Tokens, Token{
		ID:        tokenIDFor(node),
		TypeName:  fmt.Sprintf("%T", node),
		Line:      pos.Line,
		EndLine:   end.Line,
		Offset:    pos.Offset,
		EndOffset: end.Offset,
	})

	size := 1
	for _, child := range childrenOfNode(node) {
		size += t.walk(child)
	}
	t.file.Tokens[index].SubtreeSize = size
	return size
}

func childrenOfNode(node ast.Node) []ast.Node {
	switch n := node.(type) {
	case *ast.File:
		children := make([]ast.Node, 0, len(n.Decls))
		for _, decl := range n.Decls {
			children = append(children, decl)
		}
		return children
	case *ast.Field:
		children := make([]ast.Node, 0, len(n.Names)+1)
		for _, name := range n.Names {
			children = append(children, name)
		}
		if n.Type != nil {
			children = append(children, n.Type)
		}
		return children
	case *ast.FuncType:
		var children []ast.Node
		if n.Params != nil {
			children = append(children, n.Params)
		}
		if n.Results != nil {
			children = append(children, n.Results)
		}
		return children
	case *ast.TypeSpec:
		children := []ast.Node{n.Name}
		if n.Type != nil {
			children = append(children, n.Type)
		}
		return children
	}

	collector := &childCollector{root: node}
	ast.Walk(collector, node)
	children := make([]ast.Node, 0, len(collector.children))
	for _, child := range collector.children {
		switch child.(type) {
		case *ast.Comment, *ast.CommentGroup:
			continue
		}
		children = append(children, child)
	}
	return children
}

// childCollector collects the immediate children of its root node. It relies
// on ast.Walk visiting the root first and then each child with the visitor
// returned for the root.
type childCollector struct {
	root     ast.Node
	seenRoot bool
	children []ast.Node
}

func (c *childCollector) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}
	if !c.seenRoot && node == c.root {
		c.seenRoot = true
		return c
	}
	c.children = append(c.children, node)
	return nil
}
