func buildSuffixArray(symbols []int) []int {
	n := len(symbols)
	sa := make([]int, n)
	rank := make([]int, n)
	for i, symbol := range symbols {
		sa[i] = i
		rank[i] = symbol
	}
	tmp := make([]int, n)
	for k := 1; k < n; k <<= 1 {
		sort.Slice(sa, func(a, b int) bool {
			i, j := sa[a], sa[b]
			if rank[i] != rank[j] {
				return rank[i] < rank[j]
			}
			ri, rj := -1, -1
			if i+k < n {
				ri = rank[i+k]
			}
			if j+k < n {
				rj = rank[j+k]
			}
			return ri < rj
		})
		tmp[sa[0]] = 0
		r := 0
		for i := 1; i < n; i++ {
			cur, prev := sa[i], sa[i-1]
			ri, rp := -1, -1
			if cur+k < n {
				ri = rank[cur+k]
			}
			if prev+k < n {
				rp = rank[prev+k]
			}
			if rank[cur] != rank[prev] || ri != rp {
				r++
			}
			tmp[cur] = r
		}
		copy(rank, tmp)
		if r == n-1 {
			break
		}
	}
