func buildLCP(symbols []int, sa []int) []int {
	n := len(symbols)
	lcp := make([]int, n)
	rankPos := make([]int, n)
	for i, pos := range sa {
		rankPos[pos] = i
	}
	h := 0
	for i := 0; i < n; i++ {
		r := rankPos[i]
		if r == 0 {
			continue
		}
		j := sa[r-1]
		for i+h < n && j+h < n && symbols[i+h] == symbols[j+h] {
			h++
		}
		lcp[r] = h
		if h > 0 {
			h--
		}
	}
	return lcp
}

func lessBoundaries(lcp []int) (prevLess, nextLess []int) {
	n := len(lcp)
	prevLess = make([]int, n)
	nextLess = make([]int, n)
	stack := make([]int, 0, n)
	for i := 0; i < n; i++ {
		for len(stack) > 0 && lcp[stack[len(stack)-1]] >= lcp[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) == 0 {
			prevLess[i] = 0
		} else {
			prevLess[i] = stack[len(stack)-1]
		}
		stack = append(stack, i)
	}
	stack = stack[:0]
	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && lcp[stack[len(stack)-1]] >= lcp[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) == 0 {
			nextLess[i] = n
		} else {
			nextLess[i] = stack[len(stack)-1]
		}
		stack = append(stack, i)
	}
	return prevLess, nextLess
}
