package main

import (
	"sort"
	"strings"
)

type Clone struct {
	Filename string
	Start    int
	End      int

	file        *SourceFile
	fileIndex   int
	startTok    int // index in its file
	endTok      int // exclusive index in its file
	startOffset int
	endOffset   int
}

type Group struct {
	Clones []*Clone
}

type globalTokenRef struct {
	fileIndex  int
	tokenIndex int
	token      *Token
}

// FindClones finds clone groups in the parsed files. It constructs a suffix
// array for the concatenated token stream and enumerates the maximal
// repeated substrings (the intervals of the suffix array whose least common
// prefixes are locally minimal). Each such substring is then broken into
// the largest syntax subtrees completely contained within it; a reported
// fragment is a trailing run of those subtrees that individually meet the
// size threshold.
func FindClones(files []*SourceFile, threshold int) []*Group {
	if threshold < 1 {
		threshold = 1
	}
	// Build the concatenated token stream, with a unique separator symbol
	// between different parsed files.
	var refs []globalTokenRef
	var symbols []int
	for fileIndex, file := range files {
		for tokenIndex := range file.Tokens {
			tok := &file.Tokens[tokenIndex]
			tok.FileIndex = fileIndex
			tok.IndexInFile = tokenIndex
			refs = append(refs, globalTokenRef{fileIndex: fileIndex, tokenIndex: tokenIndex, token: tok})
			symbols = append(symbols, tok.ID+len(files)+5)
		}
		// Unique separator for this file.
		refs = append(refs, globalTokenRef{fileIndex: -1, tokenIndex: -1, token: nil})
		symbols = append(symbols, fileIndex+1)
	}
	n := len(symbols)
	if n == 0 {
		return nil
	}

	sa := buildSuffixArray(symbols)
	if len(sa) == 0 {
		return nil
	}
	lcp := buildLCP(symbols, sa)
	prevLess, nextLess := lessBoundaries(lcp)

	type intervalKey struct{ l, r, length int }
	seenInterval := make(map[intervalKey]bool)
	var groups []*Group
	seenGroup := make(map[string]bool)

	for boundary := 1; boundary < n; boundary++ {
		length := lcp[boundary]
		if length < threshold {
			continue
		}
		key := intervalKey{l: prevLess[boundary], r: nextLess[boundary], length: length}
		if key.r-key.l < 2 {
			continue
		}
		if seenInterval[key] {
			continue
		}
		seenInterval[key] = true

		occurrences := make([]int, 0, key.r-key.l)
		for _, pos := range sa[key.l:key.r] {
			if pos >= 0 && pos < len(refs) && refs[pos].token != nil {
				occurrences = append(occurrences, pos)
			}
		}
		if len(occurrences) < 2 {
			continue
		}
		sort.Ints(occurrences)
		group := groupFromCandidate(files, refs, occurrences, length, threshold)
		if group == nil {
			continue
		}
		gkey := groupKey(group)
		if seenGroup[gkey] {
			continue
		}
		seenGroup[gkey] = true
		groups = append(groups, group)
	}

	groups = removeSubsumedGroups(groups)
	return groups
}

func groupFromCandidate(files []*SourceFile, refs []globalTokenRef, occurrences []int, length, threshold int) *Group {
	// Determine a segmentation using the earliest occurrence.
	var segments []int
	for _, occ := range occurrences {
		segments = segmentCandidate(refs, occ, length)
		if segments != nil {
			break
		}
	}
	if segments == nil {
		return nil
	}

	// Find runs of segments that each meet the threshold and choose the
	// last such run.
	type segRun struct{ startSeg, endSeg, startOffset, tokenLen int }
	var runs []segRun
	for i := 0; i < len(segments); {
		if segments[i] < threshold {
			i++
			continue
		}
		j := i
		offset := 0
		for k := 0; k < i; k++ {
			offset += segments[k]
		}
		startOffset := offset
		tokenLen := 0
		for j < len(segments) && segments[j] >= threshold {
			tokenLen += segments[j]
			j++
		}
		runs = append(runs, segRun{startSeg: i, endSeg: j, startOffset: startOffset, tokenLen: tokenLen})
		i = j
	}
	if len(runs) == 0 {
		return nil
	}
	run := runs[len(runs)-1]

	clonesByKey := make(map[string]*Clone)
	var clones []*Clone
	for _, occ := range occurrences {
		startGlobal := occ + run.startOffset
		endGlobal := startGlobal + run.tokenLen
		if startGlobal < 0 || endGlobal > len(refs) || startGlobal >= len(refs) {
			continue
		}
		startRef := refs[startGlobal]
		if startRef.token == nil {
			continue
		}
		file := files[startRef.fileIndex]
		startTok := startRef.token
		// Find last segment's root token to obtain a sensible end.
		// The last segment begins at endGlobal minus its size.
		lastSegSize := segments[run.endSeg-1]
		lastSegStartGlobal := endGlobal - lastSegSize
		if lastSegStartGlobal < 0 || lastSegStartGlobal >= len(refs) {
			continue
		}
		lastRef := refs[lastSegStartGlobal]
		if lastRef.token == nil || lastRef.fileIndex != startRef.fileIndex {
			// If the run would cross between files, ignore the occurrence.
			if lastRef.token == nil {
				continue
			}
		}
		endLine := lastRef.token.EndLine
		endOffset := lastRef.token.EndOffset
		// In a run made of a single partially represented token (which can
		// only happen with a threshold of 1), fall back to the last token
		// inside the run.
		if run.endSeg-run.startSeg == 1 && lastSegSize == 1 && endGlobal-1 >= startGlobal {
			if lastTokRef := refs[endGlobal-1]; lastTokRef.token != nil && lastSegStartGlobal == startGlobal && lastRef.token.SubtreeSize > length {
				endLine = lastTokRef.token.Line
				endOffset = lastTokRef.token.EndOffset
			}
		}
		clone := &Clone{
			Filename:    file.Name,
			Start:       startTok.Line,
			End:         endLine,
			file:        file,
			fileIndex:   startRef.fileIndex,
			startTok:    startRef.tokenIndex,
			endTok:      startRef.tokenIndex + run.tokenLen,
			startOffset: startTok.Offset,
			endOffset:   endOffset,
		}
		key := clone.Filename + "\x00" + itoa(clone.startTok) + "\x00" + itoa(clone.endTok)
		if _, exists := clonesByKey[key]; exists {
			continue
		}
		clonesByKey[key] = clone
		clones = append(clones, clone)
	}
	if len(clones) < 2 {
		return nil
	}
	return &Group{Clones: clones}
}

func segmentCandidate(refs []globalTokenRef, occ, length int) []int {
	if occ < 0 || occ+length > len(refs) {
		return nil
	}
	segments := make([]int, 0, 8)
	for offset := 0; offset < length; {
		ref := refs[occ+offset]
		if ref.token == nil {
			return nil
		}
		size := ref.token.SubtreeSize
		if size <= 0 {
			size = 1
		}
		if offset+size <= length {
			segments = append(segments, size)
			offset += size
		} else {
			segments = append(segments, 1)
			offset++
		}
	}
	return segments
}

func groupKey(group *Group) string {
	clones := sortedClones(group.Clones)
	var b strings.Builder
	for _, clone := range clones {
		b.WriteString(clone.Filename)
		b.WriteByte(0)
		b.WriteString(itoa(clone.startTok))
		b.WriteByte(0)
		b.WriteString(itoa(clone.endTok))
		b.WriteByte('\n')
	}
	return b.String()
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// removeSubsumedGroups removes groups whose clones are all strictly
// contained within the clones of another group having the same number of
// clones.
func removeSubsumedGroups(groups []*Group) []*Group {
	if len(groups) < 2 {
		return groups
	}
	removed := make([]bool, len(groups))
	for i, small := range groups {
		for j, large := range groups {
			if i == j || len(small.Clones) != len(large.Clones) {
				continue
			}
			if groupContainedIn(small, large) {
				removed[i] = true
				break
			}
		}
	}
	out := groups[:0]
	// Rebuild rather than mutating the argument's backing array in place
	// in a way that loses entries while iterating above (we already
	// finished comparisons).
	out = nil
	for i, group := range groups {
		if !removed[i] {
			out = append(out, group)
		}
	}
	return out
}

func groupContainedIn(small, large *Group) bool {
	used := make([]bool, len(large.Clones))
	strict := false
	for _, sc := range small.Clones {
		found := false
		for i, lc := range large.Clones {
			if used[i] || sc.Filename != lc.Filename {
				continue
			}
			if lc.startTok <= sc.startTok && sc.endTok <= lc.endTok && lc.fileIndex == sc.fileIndex || lc.Filename == sc.Filename && lc.startTok <= sc.startTok && sc.endTok <= lc.endTok {
				// Match by filename and token positions in that file. File
				// indexes can differ for the same filename supplied twice.
				if lc.startTok <= sc.startTok && sc.endTok <= lc.endTok {
					used[i] = true
					found = true
					if lc.startTok < sc.startTok || sc.endTok < lc.endTok {
						strict = true
					}
					break
				}
			}
		}
		if !found {
			return false
		}
	}
	return strict
}

func buildSuffixArray(symbols []int) []int {
	n := len(symbols)
	sa := make([]int, n)
	rank := make([]int, n)
	for i, symbol := range symbols {
		sa[i] = i
		rank[i] = symbol
	}
	tmp := make([]int, n)
	for k := 1; k < n; k <<= 1 {
		sort.Slice(sa, func(a, b int) bool {
			i, j := sa[a], sa[b]
			if rank[i] != rank[j] {
				return rank[i] < rank[j]
			}
			ri, rj := -1, -1
			if i+k < n {
				ri = rank[i+k]
			}
			if j+k < n {
				rj = rank[j+k]
			}
			return ri < rj
		})
		tmp[sa[0]] = 0
		r := 0
		for i := 1; i < n; i++ {
			cur, prev := sa[i], sa[i-1]
			ri, rp := -1, -1
			if cur+k < n {
				ri = rank[cur+k]
			}
			if prev+k < n {
				rp = rank[prev+k]
			}
			if rank[cur] != rank[prev] || ri != rp {
				r++
			}
			tmp[cur] = r
		}
		copy(rank, tmp)
		if r == n-1 {
			break
		}
	}
	return sa
}

func buildLCP(symbols []int, sa []int) []int {
	n := len(symbols)
	lcp := make([]int, n)
	rankPos := make([]int, n)
	for i, pos := range sa {
		rankPos[pos] = i
	}
	h := 0
	for i := 0; i < n; i++ {
		r := rankPos[i]
		if r == 0 {
			continue
		}
		j := sa[r-1]
		for i+h < n && j+h < n && symbols[i+h] == symbols[j+h] {
			h++
		}
		lcp[r] = h
		if h > 0 {
			h--
		}
	}
	return lcp
}

func lessBoundaries(lcp []int) (prevLess, nextLess []int) {
	n := len(lcp)
	prevLess = make([]int, n)
	nextLess = make([]int, n)
	stack := make([]int, 0, n)
	for i := 0; i < n; i++ {
		for len(stack) > 0 && lcp[stack[len(stack)-1]] >= lcp[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) == 0 {
			prevLess[i] = 0
		} else {
			prevLess[i] = stack[len(stack)-1]
		}
		stack = append(stack, i)
	}
	stack = stack[:0]
	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && lcp[stack[len(stack)-1]] >= lcp[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) == 0 {
			nextLess[i] = n
		} else {
			nextLess[i] = stack[len(stack)-1]
		}
		stack = append(stack, i)
	}
	return prevLess, nextLess
}
