// suffix-array intervals are contained in it, and sibling candidates are
// visited in suffix-array order.
func orderGroups(groups []*Group) []*Group {
	if len(groups) < 2 {
		return groups
	}
	contains := func(a, b *Group) bool {
		return a != b && a.candLen < b.candLen && a.candL <= b.candL && b.candR <= a.candR
	}
	parentOf := make([]*Group, len(groups))
	for i, group := range groups {
		var best *Group
		for _, other := range groups {
			if contains(other, group) {
				if best == nil || other.candLen > best.candLen {
					best = other
				}
			}
		}
		parentOf[i] = best
	}
	byInterval := func(list []*Group) {
		sort.SliceStable(list, func(i, j int) bool {
			if list[i].candL != list[j].candL {
				return list[i].candL < list[j].candL
			}
			if list[i].candLen != list[j].candLen {
				return list[i].candLen < list[j].candLen
			}
			return list[i].candR > list[j].candR
		})
	}
	var roots []*Group
	children := make(map[*Group][]*Group)
	indexOf := make(map[*Group]int, len(groups))
	for i, group := range groups {
		indexOf[group] = i
	}
	for i, group := range groups {
		if parentOf[i] == nil {
			roots = append(roots, group)
		} else {
			children[parentOf[i]] = append(children[parentOf[i]], group)
		}
	}
	byInterval(roots)
	for _, list := range children {
		byInterval(list)
	}
	out := make([]*Group, 0, len(groups))
	var visit func(group *Group)
	visit = func(group *Group) {
		out = append(out, group)
		for _, child := range children[group] {
			visit(child)
		}
	}
	for _, root := range roots {
		visit(root)
	}
	if len(out) != len(groups) {
		return groups
	}
	return out
}
