// removeSequenceGroupsContainedInSubtreeGroups drops multi-subtree clone
// groups whose fragments all lie inside fragments of groups that each
// correspond to a single syntax subtree.
func removeSequenceGroupsContainedInSubtreeGroups(groups []*Group) []*Group {
	isSingle := make([]bool, len(groups))
	for i, group := range groups {
		single := len(group.Clones) > 0
		for _, clone := range group.Clones {
			if clone.file == nil || clone.startTok < 0 || clone.startTok >= len(clone.file.Tokens) {
				single = false
				break
			}
			if clone.file.Tokens[clone.startTok].SubtreeSize != clone.endTok-clone.startTok {
				single = false
				break
			}
		}
		isSingle[i] = single
	}
	var subtreeClones []*Clone
	for i, group := range groups {
		if isSingle[i] {
			subtreeClones = append(subtreeClones, group.Clones...)
		}
	}
	if len(subtreeClones) == 0 {
		return groups
	}
	out := make([]*Group, 0, len(groups))
	for i, group := range groups {
		if isSingle[i] {
			out = append(out, group)
			continue
		}
		allContained := len(group.Clones) > 0
		for _, clone := range group.Clones {
			contained := false
			for _, large := range subtreeClones {
				if large == clone {
					continue
				}
				if clone.Filename == large.Filename && large.startTok <= clone.startTok && clone.endTok <= large.endTok {
					contained = true
					break
				}
			}
			if !contained {
				allContained = false
				break
			}
		}
		if !allContained {
			out = append(out, group)
		}
	}
	return out
}
